Exception assertEx = new AssertException('assert message');
System.assertEquals('assert message', assertEx.getMessage());
System.assertEquals('System.AssertException', assertEx.getTypeName());
System.assertEquals(0, assertEx.getLineNumber());
System.assertEquals('', assertEx.getStackTraceString());
System.assertEquals(0, assertEx.getInaccessibleFields().size());
assertEx.setMessage('changed assert');
System.assertEquals('changed assert', assertEx.getMessage());
Exception assertCause = new DmlException('assert cause');
System.assertEquals(assertEx, assertEx.initCause(assertCause));
System.assertEquals('assert cause', assertEx.getCause().getMessage());
Exception asyncEx = new AsyncException('async message');
System.assertEquals('async message', asyncEx.getMessage());
System.assertEquals('System.AsyncException', asyncEx.getTypeName());
System.assertEquals(0, asyncEx.getLineNumber());
System.assertEquals('', asyncEx.getStackTraceString());
System.assertEquals(0, asyncEx.getInaccessibleFields().size());
asyncEx.setMessage('changed async');
System.assertEquals('changed async', asyncEx.getMessage());
Exception asyncCause = new DmlException('async cause');
System.assertEquals(asyncEx, asyncEx.initCause(asyncCause));
System.assertEquals('async cause', asyncEx.getCause().getMessage());

